// What `software-factory check` looks at in Kobble's files: that each file
// fits, and that what a record names is there (the personas, and an
// exploration's copy of each signal it heard); and the made-up world's
// situations (situations.ts), with the situation each persona names. Each
// problem starts with where it is.
import { existsSync } from "node:fs";
import { findProducts } from "../products/find-products.js";
import { messageOf } from "../products/product.js";
import { Situations, situationProblems } from "./situations.js";
import { KOBBLE_FOLDER, KobbleStore } from "./store.js";
export function checkKobbleIn(factory) {
    const store = new KobbleStore(factory);
    const { products } = findProducts(factory);
    const worlds = situationProblems(products);
    if (!existsSync(store.root))
        return {
            checked: products.some((product) => product.world),
            problems: worlds,
        };
    return {
        checked: true,
        problems: [...worlds, ...recordProblems(store, products)],
    };
}
// What is wrong with Kobble's records.
function recordProblems(store, products) {
    const problems = [];
    // What could be read; null when a file did not fit, so what it names is
    // not checked against it.
    const read = (what) => {
        try {
            return what();
        }
        catch (error) {
            problems.push(`${KOBBLE_FOLDER}/${messageOf(error)}`);
            return null;
        }
    };
    const signals = read(() => store.all("signals")) ?? [];
    const personas = read(() => store.all("personas"));
    const explorations = read(() => store.all("explorations")) ?? [];
    const tests = read(() => store.all("tests")) ?? [];
    read(() => [store.sync()]);
    for (const one of explorations) {
        for (const board of read(() => [store.board(one.id)]) ?? [])
            problems.push(...arrowProblems(one.id, board));
        read(() => [store.world(one.id)]);
    }
    const keys = new Situations(() => products).names().map((one) => one.key);
    problems.push(...situationNamed(personas ?? [], keys));
    const known = (ids) => ({
        has: (id) => ids === null || ids.some((one) => one.id === id),
    });
    const persona = known(personas);
    // Each file, with the personas it names and what else it misses. An
    // exploration keeps its own copy of what it heard: the signal files
    // themselves stay on the computer that read the live app.
    const naming = [
        ...signals.map((one) => ({
            where: `signals/${one.id}.json`,
            personas: one.persona ? [one.persona] : [],
            missing: [],
        })),
        ...explorations.map((one) => ({
            where: `explorations/${one.id}/exploration.json`,
            personas: one.personas,
            missing: one.signals
                .filter((id) => !one.heard.some((heard) => heard.id === id))
                .map((id) => `copy of the signal “${id}” it heard`),
        })),
        ...tests.map((one) => ({
            where: `tests/${one.id}.json`,
            personas: [one.persona],
            missing: [],
        })),
    ];
    for (const { where, personas: named, missing } of naming) {
        const gone = [
            ...named.filter((id) => !persona.has(id)).map((id) => `persona “${id}”`),
            ...missing,
        ];
        for (const what of gone)
            problems.push(`${KOBBLE_FOLDER}/${where}: there is no ${what}.`);
    }
    return problems;
}
// The personas that name a situation there is not.
function situationNamed(personas, keys) {
    return personas
        .filter((one) => one.situation && !keys.includes(one.situation))
        .map((one) => `${KOBBLE_FOLDER}/personas/${one.id}.json: there is no situation “${one.situation ?? ""}”.`);
}
// A board's arrows that join a thing not on it.
function arrowProblems(id, board) {
    const on = new Set(["problem", "heard", ...board.things.map((t) => t.id)]);
    return board.links
        .filter((link) => !on.has(link.from) || !on.has(link.to))
        .map((link) => `${KOBBLE_FOLDER}/explorations/${id}/board.json: the arrow ${link.id} joins a thing that is not there.`);
}
